import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

import { World } from './world.js';
import { Player } from './player.js';
import { EnemyManager } from './enemy.js';
import { Combat } from './combat.js';
import { UI } from './ui.js';
import { Input } from './input.js';
import { Effects } from './effects.js';
import { AudioSys } from './audio.js';

const canvas = document.createElement('canvas');
document.getElementById('game').appendChild(canvas);

const renderer = new THREE.WebGLRenderer({ canvas, antialias:true, alpha:false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x050a18, 0.022);

const camera = new THREE.PerspectiveCamera(60, window.innerWidth/window.innerHeight, 0.1, 300);
camera.position.set(0, 8, 12);

const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.7, 0.4, 0.85);
composer.addPass(bloom);
composer.addPass(new OutputPass());

const world = new World(scene);
const effects = new Effects(scene);
const audio = new AudioSys();
const input = new Input();
const player = new Player(scene, camera, input, audio, effects);
const enemies = new EnemyManager(scene, player, audio, effects);
const combat = new Combat(player, enemies, effects, audio);
const ui = new UI(player, enemies);

let state = 'menu'; // menu | playing | paused | dead
let lastTime = performance.now();
let wave = 1;
let xp = 0, level = 1, xpNeed = 100, talentPoints = 0;

player.onLevelUp = () => { level++; talentPoints++; xpNeed = Math.floor(xpNeed*1.35); ui.toast('Level Up!'); audio.play('level'); };
player.stats.level = () => level;

function applyLevelStats() {
  player.maxHp = 100 + (level-1)*15;
  player.maxStamina = 100 + (level-1)*5;
  player.maxMana = 60 + (level-1)*10;
  if (player.hp > player.maxHp) player.hp = player.maxHp;
}

player.applyLevelStats = applyLevelStats;

function startGame() {
  state = 'playing';
  document.getElementById('mainMenu').classList.add('hidden');
  document.getElementById('deathMenu').classList.add('hidden');
  document.getElementById('pauseMenu').classList.add('hidden');
  resetRun();
  input.requestPointerLock();
}

function resetRun() {
  level = 1; xp = 0; xpNeed = 100; talentPoints = 0; wave = 1;
  player.reset();
  applyLevelStats();
  player.hp = player.maxHp; player.stamina = player.maxStamina; player.mana = player.maxMana;
  enemies.clear();
  enemies.spawnWave(wave);
  ui.update();
}

function gameOver() {
  state = 'dead';
  document.exitPointerLock?.();
  document.getElementById('deathMenu').classList.remove('hidden');
  audio.play('death');
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth/window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  composer.setSize(window.innerWidth, window.innerHeight);
  bloom.resolution.set(window.innerWidth, window.innerHeight);
});

// Menu buttons
document.getElementById('playBtn').addEventListener('click', startGame);
document.getElementById('respawnBtn').addEventListener('click', () => { startGame(); });
document.getElementById('quitBtn').addEventListener('click', () => {
  state = 'menu';
  document.getElementById('pauseMenu').classList.add('hidden');
  document.getElementById('mainMenu').classList.remove('hidden');
  document.exitPointerLock?.();
  enemies.clear();
});
document.getElementById('resumeBtn').addEventListener('click', () => {
  state = 'playing';
  document.getElementById('pauseMenu').classList.add('hidden');
  input.requestPointerLock();
});

// Talent buttons
document.querySelectorAll('[data-talent]').forEach(b => {
  b.addEventListener('click', () => {
    if (talentPoints <= 0) { ui.toast('No talent points'); return; }
    const t = b.dataset.talent;
    if (t === 'vitality') { player.talents.vitality++; player.maxHp += 20; player.hp = Math.min(player.hp+20, player.maxHp); }
    if (t === 'strength') { player.talents.strength++; player.damage += 5; }
    if (t === 'arcane') { player.talents.arcane++; player.maxMana += 20; player.mana = Math.min(player.mana+20, player.maxMana); }
    talentPoints--;
    ui.update();
    ui.toast('Talent learned');
  });
});

// Hotbar
document.querySelectorAll('.slot').forEach(s => {
  s.addEventListener('click', () => {
    const i = +s.dataset.slot;
    player.selectSlot(i);
    document.querySelectorAll('.slot').forEach(x=>x.classList.remove('active'));
    s.classList.add('active');
  });
});

input.on('pause', () => {
  if (state === 'playing') { state = 'paused'; document.exitPointerLock?.(); document.getElementById('pauseMenu').classList.remove('hidden'); }
  else if (state === 'paused') { state = 'playing'; document.getElementById('pauseMenu').classList.add('hidden'); input.requestPointerLock(); }
});

function loop(now) {
  const dt = Math.min(0.05, (now - lastTime)/1000);
  lastTime = now;
  if (state === 'playing') {
    player.update(dt);
    enemies.update(dt);
    combat.update(dt);
    // XP / level
    if (player.pendingXp > 0) {
      xp += player.pendingXp; player.pendingXp = 0;
      while (xp >= xpNeed) { xp -= xpNeed; player.onLevelUp(); applyLevelStats(); }
    }
    // wave progression
    if (enemies.count() === 0) {
      wave++;
      enemies.spawnWave(wave);
      ui.toast('Wave ' + wave);
    }
    if (player.hp <= 0 && state === 'playing') gameOver();
  }
  world.update(dt);
  effects.update(dt);
  ui.update();
  // camera follow
  player.updateCamera(camera);
  composer.render();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

// Expose for debugging
window.game = { state: () => state, player, enemies };

export { state };

import * as THREE from 'three';

export class World {
  constructor(scene) {
    this.scene = scene;
    this.time = 0;
    this.build();
  }
  build() {
    const scene = this.scene;
    // Sky / fog handled in main; add hemisphere
    const hemi = new THREE.HemisphereLight(0x1a2a4a, 0x050508, 0.6);
    scene.add(hemi);
    const dir = new THREE.DirectionalLight(0x6fa8ff, 1.2);
    dir.position.set(30, 50, 20);
    dir.castShadow = true;
    dir.shadow.mapSize.set(2048,2048);
    dir.shadow.camera.near = 1; dir.shadow.camera.far = 120;
    dir.shadow.camera.left = -60; dir.shadow.camera.right = 60;
    dir.shadow.camera.top = 60; dir.shadow.camera.bottom = -60;
    scene.add(dir);

    // Ground arena - circular platform
    const groundGeo = new THREE.CircleGeometry(45, 64);
    const groundMat = new THREE.MeshStandardMaterial({ color:0x1a1f2e, roughness:0.9, metalness:0.1 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI/2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Grid lines
    const grid = new THREE.GridHelper(90, 45, 0x1f3355, 0x111a2a);
    grid.position.y = 0.01;
    scene.add(grid);

    // Ring wall
    const wallGeo = new THREE.CylinderGeometry(48, 48, 6, 64, 1, true);
    const wallMat = new THREE.MeshStandardMaterial({ color:0x0c1020, roughness:1, side:THREE.DoubleSide });
    const wall = new THREE.Mesh(wallGeo, wallMat);
    wall.position.y = 3;
    scene.add(wall);

    // Pillars
    for (let i=0;i<12;i++){
      const a = i/12*Math.PI*2;
      const r = 30;
      const h = 4 + Math.random()*4;
      const geo = new THREE.CylinderGeometry(0.6,0.8,h,8);
      const mat = new THREE.MeshStandardMaterial({ color:0x22283a, roughness:0.8, metalness:0.2 });
      const m = new THREE.Mesh(geo, mat);
      m.position.set(Math.cos(a)*r, h/2, Math.sin(a)*r);
      m.castShadow = true; m.receiveShadow = true;
      scene.add(m);
      // crystal on top
      const cgeo = new THREE.OctahedronGeometry(0.5);
      const cmat = new THREE.MeshStandardMaterial({ color:0x3498db, emissive:0x3498db, emissiveIntensity:1.5, roughness:0.2 });
      const c = new THREE.Mesh(cgeo, cmat);
      c.position.set(Math.cos(a)*r, h+0.6, Math.sin(a)*r);
      scene.add(c);
      this.crystals = this.crystals || [];
      this.crystals.push(c);
    }

    // Platforms
    for (let i=0;i<5;i++){
      const x = (Math.random()-0.5)*40;
      const z = (Math.random()-0.5)*40;
      const h = 1 + Math.random()*2;
      const geo = new THREE.BoxGeometry(6, h, 6);
      const mat = new THREE.MeshStandardMaterial({ color:0x1e2638, roughness:0.85 });
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, h/2, z);
      m.castShadow = true; m.receiveShadow = true;
      scene.add(m);
    }

    // Ambient particles
    const pCount = 400;
    const pos = new Float32Array(pCount*3);
    for (let i=0;i<pCount;i++){ pos[i*3]=(Math.random()-0.5)*90; pos[i*3+1]=Math.random()*20; pos[i*3+2]=(Math.random()-0.5)*90; }
    const pgeo = new THREE.BufferGeometry();
    pgeo.setAttribute('position', new THREE.BufferAttribute(pos,3));
    const pmat = new THREE.PointsMaterial({ color:0x6fa8ff, size:0.15, transparent:true, opacity:0.6, sizeAttenuation:true });
    this.particles = new THREE.Points(pgeo, pmat);
    scene.add(this.particles);

    // Light points
    for (let i=0;i<6;i++){
      const a = i/6*Math.PI*2;
      const pl = new THREE.PointLight(0x3498db, 1.2, 25);
      pl.position.set(Math.cos(a)*20, 3, Math.sin(a)*20);
      scene.add(pl);
    }
  }
  update(dt) {
    this.time += dt;
    if (this.crystals) this.crystals.forEach((c,i) => { c.rotation.y += dt*0.8; c.position.y += Math.sin(this.time*2+i)*0.002; });
    if (this.particles) { this.particles.rotation.y += dt*0.02; }
  }
}

import * as THREE from 'three';

export class Player {
  constructor(scene, camera, input, audio, effects) {
    this.scene = scene;
    this.camera = camera;
    this.input = input;
    this.audio = audio;
    this.effects = effects;

    this.group = new THREE.Group();
    this.buildMesh();
    scene.add(this.group);

    // stats
    this.maxHp = 100; this.hp = 100;
    this.maxStamina = 100; this.stamina = 100;
    this.maxMana = 60; this.mana = 60;
    this.damage = 18;
    this.speed = 7;
    this.pendingXp = 0;
    this.talents = { vitality:0, strength:0, arcane:0 };
    this.level = 1;

    // state
    this.velocity = new THREE.Vector3();
    this.yaw = 0; this.pitch = 0;
    this.onGround = true;
    this.verticalVel = 0;
    this.gravity = -22;
    this.state = 'idle'; // idle/walk/attack/block/dodge/cast/stagger
    this.stateTimer = 0;
    this.attackCooldown = 0;
    this.blocking = false;
    this.dodgeTimer = 0;
    this.iFrames = 0;
    this.castCooldown = 0;
    this.selectedSlot = 0;
    this.spells = ['fireball','frostnova','heal'];
    this.spellNames = ['Fireball','Frost Nova','Heal'];
    this.currentSpell = 0;
    this.posture = 0; this.maxPosture = 100;
    this.postureRegen = 18;
    this.invuln = 0;

    // camera follow
    this.camDistance = 9;
    this.camHeight = 4.5;
    this.camSmooth = new THREE.Vector3(0,5,10);

    this.onLevelUp = () => {};

    // attack hit tracking
    this.attackHitSet = new Set();
    this.attackActive = false;
    this.attackTimer = 0;
    this.attackDuration = 0.45;

    // dodge
    this.dodgeDir = new THREE.Vector3();
    this.dodgeTime = 0.5;

    input.on('attack', () => this.tryAttack());
    input.on('blockStart', () => this.startBlock());
    input.on('blockEnd', () => this.endBlock());
    input.on('dodge', () => this.dodge());
    input.on('cast', () => this.cast());
    input.on('spellNext', () => this.cycleSpell(1));
    input.on('spellPrev', () => this.cycleSpell(-1));
  }

  buildMesh() {
    const g = this.group;
    // body
    const bodyMat = new THREE.MeshStandardMaterial({ color:0x1f2a3a, roughness:0.7, metalness:0.3 });
    const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.45, 1.1, 6, 12), bodyMat);
    body.position.y = 1.1;
    body.castShadow = true;
    g.add(body);
    // head
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.32, 12, 12), new THREE.MeshStandardMaterial({ color:0xd9b08c, roughness:0.8 }));
    head.position.y = 2.05;
    head.castShadow = true;
    g.add(head);
    // cloak
    const cloak = new THREE.Mesh(new THREE.ConeGeometry(0.7, 1.6, 8), new THREE.MeshStandardMaterial({ color:0x0b1a33, roughness:0.9 }));
    cloak.position.y = 1.0; cloak.rotation.x = Math.PI;
    g.add(cloak);
    // arms
    const armMat = new THREE.MeshStandardMaterial({ color:0x1f2a3a, roughness:0.7 });
    this.rightArm = new THREE.Group();
    this.rightArm.position.set(0.5, 1.5, 0);
    const armMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.12,0.12,0.7,8), armMat);
    armMesh.rotation.z = -Math.PI/2; armMesh.position.x = 0.35;
    this.rightArm.add(armMesh);
    g.add(this.rightArm);
    // sword
    this.sword = new THREE.Group();
    const blade = new THREE.Mesh(new THREE.BoxGeometry(0.06, 1.3, 0.02), new THREE.MeshStandardMaterial({ color:0xcfd8e3, metalness:0.9, roughness:0.2, emissive:0x223344, emissiveIntensity:0.3 }));
    blade.position.y = 0.65;
    this.sword.add(blade);
    const guard = new THREE.Mesh(new THREE.BoxGeometry(0.35,0.06,0.1), new THREE.MeshStandardMaterial({ color:0x7a5a2a, metalness:0.6 }));
    this.sword.add(guard);
    this.sword.position.set(0.5,1.2,0.3);
    this.sword.rotation.x = -Math.PI/4;
    g.add(this.sword);
    // left arm
    const leftArm = new THREE.Mesh(new THREE.CylinderGeometry(0.12,0.12,0.7,8), armMat);
    leftArm.rotation.z = Math.PI/2; leftArm.position.set(-0.85,1.5,0);
    g.add(leftArm);

    this.meshBody = body;
  }

  reset() {
    this.group.position.set(0,0,0);
    this.velocity.set(0,0,0);
    this.yaw = 0; this.pitch = 0;
    this.state = 'idle';
    this.attackCooldown = 0; this.castCooldown = 0;
    this.blocking = false;
    this.iFrames = 0;
    this.posture = 0;
    this.hp = this.maxHp; this.stamina = this.maxStamina; this.mana = this.maxMana;
    this.pendingXp = 0;
    this.attackHitSet.clear();
    this.attackActive = false;
  }

  selectSlot(i) {
    this.selectedSlot = i;
    if (i >= 1) this.currentSpell = i-1;
  }

  cycleSpell(dir) {
    this.currentSpell = (this.currentSpell + dir + this.spells.length) % this.spells.length;
  }

  tryAttack() {
    if (this.state === 'dead') return;
    if (this.state === 'dodge' || this.state === 'cast' || this.state === 'stagger') return;
    if (this.attackCooldown > 0) return;
    if (this.stamina < 12) { this.toast?.('Low stamina'); return; }
    this.stamina -= 12;
    this.state = 'attack';
    this.stateTimer = this.attackDuration;
    this.attackTimer = 0;
    this.attackActive = false;
    this.attackHitSet.clear();
    this.attackCooldown = 0.55;
    this.audio.play('swing');
    // arm swing
    this.sword.rotation.x = -Math.PI/2;
  }

  startBlock() {
    if (this.state === 'dead' || this.state === 'dodge' || this.state === 'stagger') return;
    this.blocking = true;
    this.state = 'block';
    this.blockStartTime = performance.now()/1000;
    this.perfectWindow = true;
  }
  endBlock() {
    if (this.state === 'block') { this.state = 'idle'; }
    this.blocking = false;
    this.perfectWindow = false;
  }

  dodge() {
    if (this.state === 'dead' || this.state === 'dodge' || this.state === 'stagger' || this.state === 'cast') return;
    if (this.stamina < 20) return;
    this.stamina -= 20;
    this.state = 'dodge';
    this.stateTimer = this.dodgeTime;
    this.iFrames = 0.45;
    // direction from input or forward
    const dir = this.input.getMoveDir(this.yaw);
    if (dir.lengthSq() < 0.01) dir.set(0,0,-1).applyAxisAngle(new THREE.Vector3(0,1,0), this.yaw);
    dir.y = 0; dir.normalize();
    this.dodgeDir.copy(dir);
    this.audio.play('dodge');
  }

  cast() {
    if (this.state === 'dead' || this.state === 'dodge' || this.state === 'stagger' || this.state === 'attack') return;
    if (this.castCooldown > 0) return;
    const spell = this.spells[this.currentSpell];
    const cost = spell === 'heal' ? 25 : 20;
    if (this.mana < cost) { this.toast?.('Low mana'); return; }
    this.mana -= cost;
    this.state = 'cast';
    this.stateTimer = 0.5;
    this.castCooldown = 0.8;
    this.audio.play('cast');
    // spawn effect via effects manager handled in combat? We'll emit event
    this.pendingCast = spell;
  }

  takeDamage(amount, fromPos, isParryable=true) {
    if (this.iFrames > 0) return false;
    if (this.state === 'block') {
      // parry check
      const now = performance.now()/1000;
      const t = now - (this.blockStartTime||0);
      if (t < 0.18 && isParryable) {
        // perfect parry
        this.effects.spawnParry(this.group.position.clone().add(new THREE.Vector3(0,1.2,0)));
        this.audio.play('parry');
        this.posture = Math.max(0, this.posture - 30);
        return 'parried';
      }
      // block reduces damage
      const reduced = amount * 0.3;
      this.hp -= reduced;
      this.stamina -= 15;
      this.posture += amount*0.6;
      this.effects.spawnHit(this.group.position.clone().add(new THREE.Vector3(0,1.2,0)), 0x3498db);
      if (this.posture >= this.maxPosture) {
        this.state = 'stagger'; this.stateTimer = 0.8; this.blocking = false;
        this.posture = this.maxPosture;
        this.audio.play('stagger');
      }
      return 'blocked';
    }
    this.hp -= amount;
    this.effects.spawnHit(this.group.position.clone().add(new THREE.Vector3(0,1.2,0)), 0xff4444);
    this.audio.play('hit');
    if (amount > 15) { this.state = 'stagger'; this.stateTimer = 0.4; }
    return 'hit';
  }

  heal(amount) {
    this.hp = Math.min(this.maxHp, this.hp + amount);
  }

  addXp(v) { this.pendingXp = (this.pendingXp||0) + v; }

  update(dt) {
    // regen
    if (this.state !== 'block') this.stamina = Math.min(this.maxStamina, this.stamina + 18*dt);
    this.mana = Math.min(this.maxMana, this.mana + 8*dt);
    this.posture = Math.max(0, this.posture - this.postureRegen*dt);
    if (this.iFrames > 0) this.iFrames -= dt;
    if (this.attackCooldown > 0) this.attackCooldown -= dt;
    if (this.castCooldown > 0) this.castCooldown -= dt;
    if (this.invuln > 0) this.invuln -= dt;

    // state timer
    if (this.stateTimer > 0) {
      this.stateTimer -= dt;
      if (this.stateTimer <= 0) {
        if (this.state === 'attack' || this.state === 'cast' || this.state === 'stagger' || this.state === 'dodge') this.state = 'idle';
      }
    }

    // attack active frames
    if (this.state === 'attack') {
      this.attackTimer += dt;
      // active from 0.12 to 0.3
      this.attackActive = (this.attackTimer >= 0.12 && this.attackTimer <= 0.3);
      // sword anim
      const t = this.attackTimer / this.attackDuration;
      this.sword.rotation.x = -Math.PI/2 + (Math.PI*0.9)*Math.sin(t*Math.PI);
      if (!this.attackActive) {}
    } else {
      this.sword.rotation.x += ( -Math.PI/4 - this.sword.rotation.x)*dt*8;
    }

    // movement
    const move = this.input.getMoveDir(this.yaw);
    const speed = (this.state === 'dodge') ? 0 : (this.state === 'attack' ? this.speed*0.5 : this.speed);
    let vx = 0, vz = 0;
    if (this.state !== 'stagger' && this.state !== 'dodge') {
      vx = move.x * speed;
      vz = move.z * speed;
    }
    if (this.state === 'dodge') {
      const t = 1 - (this.stateTimer/this.dodgeTime);
      const sp = 12*(1-t) + 2*t;
      vx = this.dodgeDir.x * sp;
      vz = this.dodgeDir.z * sp;
    }

    // gravity
    if (!this.onGround) this.verticalVel += this.gravity * dt;
    // ground check (y=0)
    this.group.position.x += vx * dt;
    this.group.position.z += vz * dt;
    this.group.position.y += this.verticalVel * dt;
    if (this.group.position.y <= 0) { this.group.position.y = 0; this.verticalVel = 0; this.onGround = true; }
    else this.onGround = false;

    // clamp arena
    const r = Math.hypot(this.group.position.x, this.group.position.z);
    if (r > 44) {
      const s = 44/r;
      this.group.position.x *= s; this.group.position.z *= s;
    }

    // jump
    if (this.input.consumeJump() && this.onGround && this.state !== 'dodge') {
      this.verticalVel = 8; this.onGround = false;
    }

    // yaw from mouse
    this.yaw = this.input.yaw;
    this.group.rotation.y = this.yaw;

    // walk bob
    const moving = Math.abs(vx)+Math.abs(vz) > 0.5;
    if (moving && this.onGround && this.state === 'idle') this.state = 'walk';
    if (!moving && this.state === 'walk') this.state = 'idle';

    // pending cast execution
    if (this.pendingCast) {
      const sp = this.pendingCast;
      this.pendingCast = null;
      this.effects.spawnCast(this.group.position.clone(), sp, this.yaw);
      // notify combat system via callback
      if (this.onCast) this.onCast(sp, this);
    }
  }

  updateCamera(camera) {
    // third person follow
    const target = this.group.position.clone().add(new THREE.Vector3(0, 1.6, 0));
    const offset = new THREE.Vector3(0, this.camHeight, this.camDistance);
    // rotate offset by yaw
    offset.applyAxisAngle(new THREE.Vector3(0,1,0), this.yaw);
    const desired = target.clone().add(offset);
    this.camSmooth.lerp(desired, 0.12);
    camera.position.copy(this.camSmooth);
    camera.lookAt(target);
  }

  getForward() {
    const v = new THREE.Vector3(0,0,-1).applyAxisAngle(new THREE.Vector3(0,1,0), this.yaw);
    return v;
  }
}

export class Input {
  constructor() {
    this.keys = {};
    this.mouse = { x:0, y:0 };
    this.yaw = 0; this.pitch = 0;
    this.pointerLocked = false;
    this.listeners = {};
    this.touch = { move:{x:0,y:0}, look:{x:0,y:0}, jump:false };
    this.jumpQueued = false;
    this._setup();
  }
  on(event, cb) { (this.listeners[event] ||= []).push(cb); }
  emit(event, ...a) { (this.listeners[event]||[]).forEach(cb=>cb(...a)); }
  _setup() {
    window.addEventListener('keydown', e => {
      this.keys[e.code] = true;
      if (e.code === 'Space') { e.preventDefault(); this.jumpQueued = true; }
      if (e.code === 'Escape') this.emit('pause');
      if (e.code === 'KeyF') this.emit('cast');
      if (e.code === 'KeyQ') this.emit('spellPrev');
      if (e.code === 'KeyE') this.emit('spellNext');
      if (e.code === 'KeyR') this.emit('cast');
      if (e.code === 'Digit1') { this.emit('slot',0); }
      if (e.code === 'Digit2') { this.emit('slot',1); }
      if (e.code === 'Digit3') { this.emit('slot',2); }
      if (e.code === 'Digit4') { this.emit('slot',3); }
    });
    window.addEventListener('keyup', e => { this.keys[e.code] = false; });
    document.addEventListener('pointerlockchange', () => { this.pointerLocked = !!document.pointerLockElement; });
    document.addEventListener('mousemove', e => {
      if (!this.pointerLocked) return;
      this.yaw -= e.movementX * 0.0025;
      this.pitch -= e.movementY * 0.0025;
      this.pitch = Math.max(-1.2, Math.min(1.2, this.pitch));
    });
    document.addEventListener('mousedown', e => {
      if (!this.pointerLocked) return;
      if (e.button === 0) this.emit('attack');
      if (e.button === 2) this.emit('blockStart');
    });
    document.addEventListener('mouseup', e => {
      if (e.button === 2) this.emit('blockEnd');
    });
    document.addEventListener('contextmenu', e => e.preventDefault());
    // keyboard block
    // (Shift to block)
    // handled in getMoveDir? no
    window.addEventListener('keydown', e => { if (e.code === 'ShiftLeft') this.emit('blockStart'); });
    window.addEventListener('keyup', e => { if (e.code === 'ShiftLeft') this.emit('blockEnd'); });
    // dodge on ctrl
    window.addEventListener('keydown', e => { if (e.code === 'ControlLeft') this.emit('dodge'); });

    // touch
    this._setupTouch();
  }
  requestPointerLock() {
    const c = document.querySelector('canvas');
    if (c && c.requestPointerLock) c.requestPointerLock();
  }
  _setupTouch() {
    const joy = document.getElementById('joystick');
    const stick = document.getElementById('stick');
    if (!joy) return;
    let active = false, origin = null;
    const start = (x,y) => { active=true; const r=joy.getBoundingClientRect(); origin={x:r.left+r.width/2,y:r.top+r.height/2}; };
    const move = (x,y) => {
      if(!active||!origin) return;
      let dx=x-origin.x, dy=y-origin.y;
      const max=40; const len=Math.hypot(dx,dy);
      if(len>max){ dx=dx/len*max; dy=dy/len*max; }
      stick.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
      this.touch.move = { x: dx/max, y: dy/max };
    };
    const end = () => { active=false; origin=null; stick.style.transform='translate(-50%,-50%)'; this.touch.move={x:0,y:0}; };
    joy.addEventListener('touchstart', e=>{ e.preventDefault(); const t=e.touches[0]; start(t.clientX,t.clientY); }, {passive:false});
    joy.addEventListener('touchmove', e=>{ e.preventDefault(); const t=e.touches[0]; move(t.clientX,t.clientY); }, {passive:false});
    joy.addEventListener('touchend', e=>{ e.preventDefault(); end(); });
    // look: right half
    let lookActive=false, last=null;
    window.addEventListener('touchstart', e=>{
      for (const t of e.changedTouches) {
        if (t.clientX > window.innerWidth*0.5) { lookActive=true; last={x:t.clientX,y:t.clientY}; }
      }
    });
    window.addEventListener('touchmove', e=>{
      for (const t of e.changedTouches) {
        if (lookActive && last) {
          this.yaw -= (t.clientX-last.x)*0.005;
          last={x:t.clientX,y:t.clientY};
        }
      }
    });
    window.addEventListener('touchend', ()=>{ lookActive=false; last=null; });
    // buttons
    const bind = (id, ev) => { const el=document.getElementById(id); if(!el) return; el.addEventListener('touchstart', e=>{ e.preventDefault(); this.emit(ev); }); };
    bind('mbAtk','attack');
    const blk=document.getElementById('mbBlk');
    if(blk){ blk.addEventListener('touchstart', e=>{e.preventDefault(); this.emit('blockStart');}); blk.addEventListener('touchend', e=>{e.preventDefault(); this.emit('blockEnd');}); }
    bind('mbDge','dodge');
    bind('mbSpl','cast');
  }
  getMoveDir(yaw) {
    let x=0, z=0;
    if (this.keys['KeyW']) z -= 1;
    if (this.keys['KeyS']) z += 1;
    if (this.keys['KeyA']) x -= 1;
    if (this.keys['KeyD']) x += 1;
    // touch
    x += this.touch.move.x;
    z += this.touch.move.y;
    const v = new THREE.Vector3(x,0,z);
    // rotate by yaw
    v.applyAxisAngle(new THREE.Vector3(0,1,0), yaw);
    // normalize
    if (v.length() > 1) v.normalize();
    return v;
  }
  consumeJump() {
    if (this.jumpQueued) { this.jumpQueued = false; return true; }
    if (this.touch.jump) { this.touch.jump = false; return true; }
    return false;
  }
}
