import * as THREE from 'three';

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.particles = [];
  }
  spawnHit(pos, color=0xff4444) {
    for (let i=0;i<12;i++){
      const m = new THREE.Mesh(new THREE.SphereGeometry(0.06,6,6), new THREE.MeshBasicMaterial({ color, transparent:true }));
      m.position.copy(pos);
      const vel = new THREE.Vector3((Math.random()-0.5)*6, Math.random()*4+1, (Math.random()-0.5)*6);
      this.particles.push({ mesh:m, vel, life:0.5, max:0.5 });
      this.scene.add(m);
    }
  }
  spawnParry(pos) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.8,0.05,8,24), new THREE.MeshBasicMaterial({ color:0xffffff, transparent:true }));
    ring.position.copy(pos);
    ring.rotation.x = Math.PI/2;
    this.particles.push({ mesh:ring, vel:new THREE.Vector3(0,0,0), life:0.4, max:0.4, scale:true });
    this.scene.add(ring);
  }
  spawnCast(pos, spell, yaw) {
    const color = spell==='fireball'?0xff6622 : spell==='frostnova'?0x66ccff : 0x66ff99;
    // muzzle flash
    const flash = new THREE.Mesh(new THREE.SphereGeometry(0.3,8,8), new THREE.MeshBasicMaterial({ color, transparent:true }));
    flash.position.copy(pos).add(new THREE.Vector3(0,1.2,0));
    this.particles.push({ mesh:flash, vel:new THREE.Vector3(0,0,0), life:0.25, max:0.25, scale:true });
    this.scene.add(flash);
  }
  spawnProjectile(start, dir, spell, onHit) {
    const color = spell==='fireball'?0xff6622:0x66ccff;
    const m = new THREE.Mesh(new THREE.SphereGeometry(0.25,8,8), new THREE.MeshStandardMaterial({ color, emissive:color, emissiveIntensity:2 }));
    m.position.copy(start);
    const light = new THREE.PointLight(color, 2, 12);
    m.add(light);
    this.scene.add(m);
    this.particles.push({ mesh:m, vel:dir.clone().multiplyScalar(22), life:3, max:3, projectile:true, spell, onHit });
  }
  spawnNova(pos) {
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.1, 0.3, 32), new THREE.MeshBasicMaterial({ color:0x66ccff, transparent:true, side:THREE.DoubleSide }));
    ring.position.copy(pos); ring.position.y = 0.1; ring.rotation.x = -Math.PI/2;
    this.scene.add(ring);
    this.particles.push({ mesh:ring, vel:new THREE.Vector3(0,0,0), life:0.6, max:0.6, nova:true });
  }
  update(dt) {
    for (let i=this.particles.length-1;i>=0;i--){
      const p = this.particles[i];
      p.life -= dt;
      if (p.projectile) {
        p.mesh.position.addScaledVector(p.vel, dt);
        // gravity light
        if (p.mesh.position.y < 0.2) { p.mesh.position.y = 0.2; }
      } else if (p.nova) {
        const s = 1 + (1 - p.life/p.max)*18;
        p.mesh.scale.set(s,s,1);
        p.mesh.material.opacity = p.life/p.max;
      } else if (p.scale) {
        const s = 1 + (1 - p.life/p.max)*2;
        p.mesh.scale.set(s,s,s);
        p.mesh.material.opacity = p.life/p.max;
      } else {
        p.mesh.position.addScaledVector(p.vel, dt);
        p.vel.y -= 9.8*dt;
        p.mesh.material.opacity = p.life/p.max;
      }
      if (p.life <= 0) {
        this.scene.remove(p.mesh);
        this.particles.splice(i,1);
      }
    }
  }
  clear() { this.particles.forEach(p=>this.scene.remove(p.mesh)); this.particles=[]; }
}

export class AudioSys {
  constructor() {
    this.ctx = null;
    this.enabled = true;
  }
  ensure() {
    if (!this.ctx) {
      try { this.ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e) { this.enabled=false; }
    }
  }
  play(name) {
    this.ensure();
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.connect(g); g.connect(ctx.destination);
    const presets = {
      swing: { f:220, type:'sawtooth', dur:0.12, vol:0.15 },
      hit: { f:120, type:'square', dur:0.15, vol:0.2 },
      parry: { f:660, type:'triangle', dur:0.2, vol:0.2 },
      stagger: { f:80, type:'sawtooth', dur:0.3, vol:0.25 },
      dodge: { f:300, type:'sine', dur:0.1, vol:0.12 },
      cast: { f:440, type:'sine', dur:0.25, vol:0.15 },
      death: { f:60, type:'sawtooth', dur:0.8, vol:0.3 },
      level: { f:880, type:'triangle', dur:0.3, vol:0.2 },
      enemy: { f:180, type:'square', dur:0.1, vol:0.15 },
    };
    const p = presets[name] || presets.hit;
    o.type = p.type;
    o.frequency.setValueAtTime(p.f, now);
    o.frequency.exponentialRampToValueAtTime(Math.max(40, p.f*0.5), now+p.dur);
    g.gain.setValueAtTime(p.vol, now);
    g.gain.exponentialRampToValueAtTime(0.001, now+p.dur);
    o.start(now); o.stop(now+p.dur);
  }
}

import * as THREE from 'three';

export class EnemyManager {
  constructor(scene, player, audio, effects) {
    this.scene = scene;
    this.player = player;
    this.audio = audio;
    this.effects = effects;
    this.enemies = [];
  }
  clear() {
    this.enemies.forEach(e => this.scene.remove(e.group));
    this.enemies = [];
  }
  count() { return this.enemies.filter(e=>e.alive).length; }
  spawnWave(wave) {
    this.clear();
    const n = Math.min(3 + wave, 10);
    for (let i=0;i<n;i++){
      const type = (i % 3 === 0 && wave>1) ? 'brute' : (i % 5 === 0 ? 'caster' : 'hollow');
      const e = new Enemy(this.scene, this.player, type, wave, this.audio, this.effects);
      // spawn around ring
      const a = Math.random()*Math.PI*2;
      const r = 18 + Math.random()*15;
      e.group.position.set(Math.cos(a)*r, 0, Math.sin(a)*r);
      this.enemies.push(e);
    }
  }
  update(dt) {
    this.enemies.forEach(e => { if (e.alive) e.update(dt); });
    // remove dead after timer
    this.enemies = this.enemies.filter(e => {
      if (!e.alive && e.removeTimer <= 0) { this.scene.remove(e.group); return false; }
      if (!e.alive) e.removeTimer -= dt;
      return true;
    });
  }
  getAlive() { return this.enemies.filter(e=>e.alive); }
}

export class Enemy {
  constructor(scene, player, type, wave, audio, effects) {
    this.scene = scene;
    this.player = player;
    this.audio = audio;
    this.effects = effects;
    this.type = type;
    this.alive = true;
    this.removeTimer = 2;
    this.wave = wave;

    // stats
    if (type === 'brute') { this.maxHp=80+wave*10; this.damage=14+wave*2; this.speed=3.5; this.xp=40; this.range=2.2; this.attackCd=1.6; }
    else if (type === 'caster') { this.maxHp=40+wave*6; this.damage=10+wave; this.speed=4; this.xp=35; this.range=12; this.attackCd=2.0; }
    else { this.maxHp=35+wave*8; this.damage=8+wave; this.speed=5; this.xp=20; this.range=1.9; this.attackCd=1.1; }
    this.hp = this.maxHp;
    this.attackTimer = 0;
    this.state = 'idle'; // idle/chase/attack/stagger/dead
    this.stateTimer = 0;
    this.staggerTimer = 0;
    this.hitFlash = 0;

    this.group = new THREE.Group();
    this.buildMesh();
    scene.add(this.group);
  }
  buildMesh() {
    const color = this.type==='brute'?0x5a3a2a : this.type==='caster'?0x3a2a5a : 0x2a4a3a;
    const size = this.type==='brute'?1.3 : 1;
    const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.4*size, 1*size, 6, 12), new THREE.MeshStandardMaterial({ color, roughness:0.8 }));
    body.position.y = 1*size;
    body.castShadow = true;
    this.group.add(body);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.28*size, 10,10), new THREE.MeshStandardMaterial({ color:0x8a6a5a, roughness:0.9 }));
    head.position.y = 1.85*size;
    this.group.add(head);
    if (this.type === 'caster') {
      const staff = new THREE.Mesh(new THREE.CylinderGeometry(0.05,0.05,1.8), new THREE.MeshStandardMaterial({ color:0x5a3a7a, emissive:0x5a3a7a, emissiveIntensity:0.5 }));
      staff.position.set(0.5,1,0); staff.rotation.z=0.2;
      this.group.add(staff);
    }
    this.bodyMesh = body;
    // health bar sprite
    const barGeo = new THREE.PlaneGeometry(1.2,0.12);
    const barMat = new THREE.MeshBasicMaterial({ color:0xff4444, side:THREE.DoubleSide });
    this.hpBar = new THREE.Mesh(barGeo, barMat);
    this.hpBar.position.y = 2.4*size;
    this.group.add(this.hpBar);
    this.hpBarBg = new THREE.Mesh(new THREE.PlaneGeometry(1.2,0.12), new THREE.MeshBasicMaterial({ color:0x222222, side:THREE.DoubleSide }));
    this.hpBarBg.position.y = 2.4*size; this.hpBarBg.position.z = -0.01;
    this.group.add(this.hpBarBg);
  }
  takeDamage(amount, fromDir) {
    if (!this.alive) return;
    this.hp -= amount;
    this.hitFlash = 0.15;
    this.effects.spawnHit(this.group.position.clone().add(new THREE.Vector3(0,1.2,0)), 0xffaa44);
    this.audio.play('enemy');
    if (this.hp <= 0) {
      this.die();
      this.player.addXp(this.xp);
      return;
    }
    // stagger
    if (amount > 8) {
      this.state = 'stagger'; this.stateTimer = 0.35;
    }
  }
  die() {
    this.alive = false;
    this.state = 'dead';
    // collapse
    this.group.rotation.x = -Math.PI/2;
    this.group.position.y = 0.3;
    this.audio.play('enemy');
  }
  update(dt) {
    if (!this.alive) { this.removeTimer -= dt; return; }
    if (this.hitFlash > 0) { this.hitFlash -= dt; this.bodyMesh.material.emissive = this.bodyMesh.material.emissive || new THREE.Color(0); this.bodyMesh.material.emissiveIntensity = this.hitFlash>0?2:0; }
    // hp bar scale
    const ratio = Math.max(0, this.hp/this.maxHp);
    this.hpBar.scale.x = ratio;
    this.hpBar.position.x = -(1-ratio)*0.6;

    // face player
    const pPos = this.player.group.position;
    const dx = pPos.x - this.group.position.x;
    const dz = pPos.z - this.group.position.z;
    const dist = Math.hypot(dx,dz);

    if (this.stateTimer > 0) { this.stateTimer -= dt; if (this.stateTimer <= 0) this.state = 'idle'; }

    if (this.state === 'stagger') return;

    // detection
    if (dist > 28) { this.state = 'idle'; return; }

    if (dist <= this.range) {
      this.state = 'attack';
      if (this.attackTimer <= 0) {
        this.attackTimer = this.attackCd;
        // telegraph + damage
        this.performAttack(dist);
      }
    } else {
      this.state = 'chase';
      // move toward player
      const nx = dx/dist, nz = dz/dist;
      this.group.position.x += nx * this.speed * dt;
      this.group.position.z += nz * this.speed * dt;
      this.group.rotation.y = Math.atan2(dx, dz);
    }

    if (this.attackTimer > 0) this.attackTimer -= dt;

    // keep on ground
    if (this.group.position.y < 0) this.group.position.y = 0;
    // clamp arena
    const r = Math.hypot(this.group.position.x, this.group.position.z);
    if (r > 44) { const s=44/r; this.group.position.x*=s; this.group.position.z*=s; }
  }
  performAttack(dist) {
    this.audio.play('enemy');
    const p = this.player;
    // caster ranged projectile
    if (this.type === 'caster') {
      const dir = new THREE.Vector3().subVectors(p.group.position, this.group.position).normalize();
      this.effects.spawnProjectile(this.group.position.clone().add(new THREE.Vector3(0,1.2,0)), dir, 'frost', (hitPos) => {
        const d = p.group.position.distanceTo(hitPos);
        if (d < 1.5) {
          const res = p.takeDamage(this.damage, this.group.position);
          if (res === 'parried') { this.takeDamage(20, p.group.position); }
        }
      });
      return;
    }
    // melee
    setTimeout(() => {
      if (!this.alive) return;
      const d = this.group.position.distanceTo(p.group.position);
      if (d <= this.range + 0.6) {
        const res = p.takeDamage(this.damage, this.group.position);
        if (res === 'parried') { this.takeDamage(25, p.group.position); this.state='stagger'; this.stateTimer=0.6; }
      }
    }, 350);
  }
}

import * as THREE from 'three';

export class Combat {
  constructor(player, enemies, effects, audio) {
    this.player = player;
    this.enemies = enemies;
    this.effects = effects;
    this.audio = audio;
    this.player.onCast = (spell, p) => this.castSpell(spell, p);
  }
  update(dt) {
    const p = this.player;
    // player melee hits
    if (p.state === 'attack' && p.attackActive) {
      const fwd = p.getForward();
      const origin = p.group.position.clone().add(new THREE.Vector3(0,1.2,0));
      for (const e of this.enemies.getAlive()) {
        if (p.attackHitSet.has(e)) continue;
        const toE = new THREE.Vector3().subVectors(e.group.position, p.group.position);
        const dist = toE.length();
        if (dist > 2.6) continue;
        toE.y = 0; toE.normalize();
        const dot = fwd.dot(toE);
        if (dot < 0.35) continue;
        // hit
        p.attackHitSet.add(e);
        const dmg = p.damage + (p.talents.strength*5);
        const res = e.takeDamage(dmg, p.group.position);
        this.effects.spawnHit(e.group.position.clone().add(new THREE.Vector3(0,1.2,0)), 0xffcc66);
        if (res !== undefined) this.audio.play('hit');
        // knockback
        const kb = toE.clone().multiplyScalar(2.5);
        e.group.position.add(kb);
      }
    }
    // projectile collisions handled in effects? We'll check projectiles here
    // iterate effects particles projectiles
    for (const part of this.effects.particles) {
      if (!part.projectile) continue;
      // check enemy hits
      for (const e of this.enemies.getAlive()) {
        if (part.hit) continue;
        const d = part.mesh.position.distanceTo(e.group.position.clone().add(new THREE.Vector3(0,1,0)));
        if (d < 1.0) {
          part.hit = true;
          part.life = 0.01;
          e.takeDamage(part.spell==='fireball'?28:22, this.player.group.position);
          this.effects.spawnHit(e.group.position.clone().add(new THREE.Vector3(0,1.2,0)), 0xff6622);
        }
      }
      // player hit by enemy projectiles? caster spawns frost with onHit callback already
    }
  }
  castSpell(spell, p) {
    const origin = p.group.position.clone().add(new THREE.Vector3(0,1.2,0));
    const fwd = p.getForward();
    if (spell === 'fireball') {
      this.effects.spawnProjectile(origin, fwd, 'fireball', null);
      this.audio.play('cast');
    } else if (spell === 'frostnova') {
      this.effects.spawnNova(p.group.position.clone());
      // damage all enemies in radius
      for (const e of this.enemies.getAlive()) {
        const d = e.group.position.distanceTo(p.group.position);
        if (d < 7) {
          e.takeDamage(20 + p.talents.arcane*4, p.group.position);
          // slow? skip
        }
      }
      this.audio.play('cast');
    } else if (spell === 'heal') {
      p.heal(35 + p.talents.arcane*5);
      this.effects.spawnHit(origin, 0x66ff99);
      this.audio.play('cast');
    }
  }
}

